def find_duplicate_items(list_1, list_2):
    if len(list_1) != len(list_2):
        return set()
    duplicate_items = set()
    for index, item in enumerate(list_1):
        if item == list_2[index]:
            duplicate_items.add(item)
    return duplicate_items
